const cat = {
  name: "Tom",
  speak() {
    return `${this.name} says ${this.sound}`;
  },
};

const dog = { name: "Rex", sound: "woof", speak: cat.speak };

console.log(cat.speak());
console.log(dog.speak());

cat.sound = "meow";
dog.name = "Max";

console.log(cat.speak());
console.log(dog.speak());
